# Banco de itens certo/errado no padrão Cebraspe, por subitem do edital (tópicos 8 e 9).
# (id, subitem, enunciado, gabarito, comentário, pegadinha ou None)

ITENS = [
# ------------------------------------------------------------------ 8 · modelos
('m01', '8', 'No patrimonialismo, o aparelho do Estado funciona como extensão do poder do soberano, e os cargos públicos são tratados como prebendas, o que favorece o nepotismo e a corrupção.',
 'Certo', 'Definição do PDRAE (1995): no patrimonialismo, res publica e res principis se confundem; cargos são prebendas ou sinecuras. Corresponde à dominação tradicional de Weber.', None),
('m02', '8', 'Na tipologia weberiana de dominação, a administração burocrática decorre da dominação carismática, fundada na crença nas qualidades excepcionais do líder.',
 'Errado', 'A burocracia é a forma típica da dominação racional-legal. A carismática se apoia no líder; a tradicional, no costume (patrimonialismo).',
 'O examinador troca os três tipos de dominação. Burocracia = racional-legal.'),
('m03', '8', 'A administração burocrática surgiu como reação ao patrimonialismo e tem como características a impessoalidade, o formalismo, a hierarquia funcional, a profissionalização e o controle rígido dos processos, realizado a priori.',
 'Certo', 'PDRAE: a burocracia nasce para combater a corrupção e o nepotismo patrimonialistas; parte da desconfiança prévia nos administradores, daí controles rígidos a priori dos processos.', None),
('m04', '8', 'O excesso de formalismo, a resistência a mudanças e a despersonalização do relacionamento são apontados por Merton como disfunções da burocracia.',
 'Certo', 'Disfunções de Merton: internalização das regras, excesso de formalismo e papelório, resistência a mudanças, despersonalização, categorização no processo decisório, superconformidade, exibição de sinais de autoridade, dificuldade no atendimento ao cliente.', None),
('m05', '8', 'Segundo o Plano Diretor da Reforma do Aparelho do Estado, de 1995, a administração gerencial rompe integralmente com a administração burocrática, abandonando princípios como a admissão por mérito e as carreiras estruturadas.',
 'Errado', 'O PDRAE diz o contrário: a administração gerencial "está apoiada na anterior, da qual conserva, embora flexibilizando, alguns dos seus princípios fundamentais", como admissão por mérito, carreiras, avaliação de desempenho e treinamento.',
 '"Rompe integralmente", "substitui por completo": os modelos se sucedem por acumulação, não por ruptura total.'),
('m06', '8', 'Na administração gerencial, o controle desloca-se dos processos para os resultados, e a estratégia apoia-se na descentralização e na delegação de autoridade aos administradores.',
 'Certo', 'PDRAE: controle a posteriori dos resultados, definição precisa de objetivos, autonomia do administrador, competição administrada, descentralização.', None),
('m07', '8', 'Para Hood (1991), a nova gestão pública combina, entre outras doutrinas, gestão profissional, padrões explícitos de desempenho, ênfase no controle de resultados, desagregação de unidades e competição no setor público.',
 'Certo', 'As sete doutrinas do NPM de Christopher Hood: gestão profissional "hands-on", padrões e medidas explícitas de desempenho, controle de outputs, desagregação, competição, estilos de gestão do setor privado, disciplina e parcimônia no uso de recursos.', None),
('m08', '8', 'A expressão "dirigir em vez de remar", associada ao governo empreendedor de Osborne e Gaebler, sintetiza a proposta do novo serviço público de Denhardt e Denhardt.',
 'Errado', '"Steering rather than rowing" é de Osborne e Gaebler (Reinventando o governo, 1992), na linha da nova gestão pública. O novo serviço público de Denhardt e Denhardt responde com "servir em vez de dirigir" (serve rather than steer).',
 'Pegadinha clássica: dirigir em vez de remar = governo empreendedor (NPM). Servir em vez de dirigir = novo serviço público.'),
('m09', '8', 'Na classificação de Abrucio, o consumerism corresponde à fase inicial do gerencialismo britânico, voltada essencialmente à redução de custos e ao aumento da eficiência.',
 'Errado', 'A fase inicial é o gerencialismo puro (managerialism), focado em economia e eficiência. O consumerism traz a qualidade e o foco no cliente-consumidor. A public service orientation (PSO) introduz cidadania, accountability, equidade e participação.',
 'Ordem das fases de Abrucio: gerencialismo puro → consumerism → PSO.'),
('m10', '8', 'O Decreto-Lei nº 200/1967 é considerado por Bresser-Pereira uma primeira tentativa de reforma gerencial no Brasil, ao promover a descentralização para a administração indireta.',
 'Certo', 'Bresser-Pereira e o PDRAE veem no DL 200/1967 um "primeiro momento da administração gerencial": transferência de atividades para autarquias, fundações, empresas públicas e sociedades de economia mista.',
 'O DASP (1936-1938, Vargas) marca a reforma burocrática. O DL 200 marca a primeira tentativa gerencial.'),
('m11', '8', 'A evolução dos modelos de gestão pública no Brasil foi linear, de modo que práticas patrimonialistas deixaram de existir com a implantação da burocracia e as práticas burocráticas desapareceram com a reforma gerencial.',
 'Errado', 'Os modelos coexistem. O próprio PDRAE reconhece a persistência de práticas patrimonialistas (clientelismo, fisiologismo), e a burocracia segue como base da gestão.', None),
('m12', '8', 'Na reforma gerencial de 1995, as atividades exclusivas de Estado, como regulamentação, fiscalização e fomento, seriam executadas por agências autônomas, e os serviços não exclusivos, como escolas e hospitais, poderiam ser transferidos para organizações sociais por meio da publicização.',
 'Certo', 'Quatro setores do PDRAE: núcleo estratégico; atividades exclusivas (agências executivas e reguladoras); serviços não exclusivos (publicização para organizações sociais); produção de bens e serviços para o mercado (privatização).',
 'Publicização ≠ privatização. Publicização é a transferência para o setor público não estatal (OS).'),

# ------------------------------------------------------------------ 8.1 · NPG
('n01', '8.1', 'Para Osborne (2006), a nova gestão pública seria um estágio transitório na evolução da administração pública tradicional para aquilo que ele denomina nova governança pública.',
 'Certo', 'Tese central do artigo "The New Public Governance?" (Public Management Review, 2006): o NPM foi um estágio relativamente breve e transitório entre a Public Administration e a NPG.', None),
('n02', '8.1', 'A nova governança pública pressupõe um Estado plural, em que múltiplos atores interdependentes contribuem para a prestação de serviços públicos, e pluralista, em que múltiplos processos informam a formulação de políticas.',
 'Certo', 'Osborne distingue "plural state" (vários atores na entrega) e "pluralist state" (vários processos na formulação). Daí o foco nas relações interorganizacionais.', None),
('n03', '8.1', 'Na nova governança pública, o principal mecanismo de coordenação é o mercado, por meio de contratos clássicos e da competição entre fornecedores independentes.',
 'Errado', 'No quadro de Osborne: PA = hierarquia; NPM = mercado e contratos clássicos ou neoclássicos; NPG = confiança e contratos relacionais.',
 'Mecanismo de governança por modelo: hierarquia (PA), mercado (NPM), confiança e redes (NPG).'),
('n04', '8.1', 'As raízes teóricas da nova governança pública, segundo Osborne, estão na teoria da escolha pública e nos estudos de gestão empresarial.',
 'Errado', 'Escolha pública e gestão empresarial são as raízes do NPM. A NPG apoia-se na sociologia institucional e na teoria de redes.', None),
('n05', '8.1', 'Enquanto a nova gestão pública tem foco intraorganizacional, a nova governança pública desloca a atenção para as relações interorganizacionais e para a governança de processos, com ênfase nos resultados efetivos dos serviços.',
 'Certo', 'É a crítica de Osborne ao NPM: foco intraorganizacional num mundo cada vez mais plural. A NPG enfatiza relações interorganizacionais, processos e outcomes.', None),
('n06', '8.1', 'Osborne apresenta a nova governança pública como o modelo definitivo, que torna obsoletos os conceitos da administração pública tradicional e da nova gestão pública.',
 'Errado', 'O título leva interrogação ("The New Public Governance?"). Osborne propõe a NPG como ferramenta conceitual, não como "one best way", e admite a convivência de elementos dos três regimes.',
 'Desconfie de "definitivo", "torna obsoleto", "supera integralmente".'),
('n07', '8.1', 'Kissler e Heidemann descrevem a governança pública como novo modelo regulatório das relações entre Estado, mercado e sociedade, marcado pela passagem de um Estado produtor do bem público para um Estado que garante e ativa a sua produção em cooperação com outros atores.',
 'Certo', 'Kissler e Heidemann (RAP, 2006): Estado de serviço produtor → Estado garantidor, ativador e cooperativo. Obra muito usada no Brasil para explicar a governança pública.', None),
('n08', '8.1', 'Na governança pública, segundo Secchi (2009), o cidadão é tratado como cliente, e a relação entre Estado e sociedade é mediada essencialmente pela lógica de mercado.',
 'Errado', 'Para Secchi, cidadão-cliente é a visão da administração pública gerencial e do governo empreendedor. Na governança pública, cidadãos e outros atores são parceiros (relação horizontal, em rede).', None),
('n09', '8.1', 'A nova governança pública e o novo serviço público são expressões sinônimas, ambas formuladas por Stephen Osborne para designar o modelo pós-gerencial.',
 'Errado', 'O novo serviço público é de Janet e Robert Denhardt (2000/2003). A NPG é de Osborne (2006/2010). São propostas pós-gerenciais próximas, mas distintas.', None),
('n10', '8.1', 'A base de valores da nova governança pública, no quadro de Osborne, é neocorporativista, ao passo que a da nova gestão pública é a crença na eficácia da competição e do mercado.',
 'Certo', 'Value base no quadro de Osborne: PA = ethos do setor público; NPM = eficácia da competição e do mercado; NPG = neocorporativista.', None),

# ------------------------------------------------------------------ 8.2 · redes e parcerias
('r01', '8.2', 'Redes de políticas públicas caracterizam-se pela interdependência entre atores e pela coordenação predominantemente horizontal, baseada em negociação e confiança, e não em hierarquia.',
 'Certo', 'Elementos clássicos das redes: interdependência de recursos, horizontalidade, negociação, confiança e objetivos compartilhados.', None),
('r02', '8.2', 'A atuação em redes de cooperação simplifica a responsabilização, uma vez que cada resultado pode ser atribuído a um único ator da rede.',
 'Errado', 'Ocorre o oposto: a responsabilização fica difusa (o "problema das muitas mãos"). Accountability é um dos principais desafios da governança em rede.', None),
('r03', '8.2', 'Os consórcios públicos podem ter personalidade jurídica de direito público, como associação pública, que integra a administração indireta de todos os entes consorciados.',
 'Certo', 'Lei 11.107/2005: associação pública (direito público, integra a indireta de todos os consorciados) ou pessoa jurídica de direito privado.', None),
('r04', '8.2', 'A União pode consorciar-se diretamente com municípios, ainda que o estado em cujo território estejam situados não participe do consórcio.',
 'Errado', 'Lei 11.107/2005, art. 1º, § 2º: a União somente participará de consórcios públicos em que também façam parte todos os estados em cujos territórios estejam situados os municípios consorciados.', None),
('r05', '8.2', 'Na concessão administrativa, modalidade de parceria público-privada, a administração pública é a usuária direta ou indireta dos serviços, e não há cobrança de tarifa dos usuários.',
 'Certo', 'Lei 11.079/2004. Concessão patrocinada: tarifa dos usuários + contraprestação pecuniária do parceiro público. Concessão administrativa: a Administração é usuária direta ou indireta.', None),
('r06', '8.2', 'É permitida a celebração de parceria público-privada cujo objeto único seja o fornecimento de mão de obra, desde que o prazo do contrato seja de, no mínimo, cinco anos.',
 'Errado', 'Lei 11.079/2004, art. 2º, § 4º: é vedada PPP com valor inferior a R$ 10 milhões, com prazo inferior a 5 anos ou que tenha como objeto único o fornecimento de mão de obra, o fornecimento e instalação de equipamentos ou a execução de obra pública. O prazo vai de 5 a 35 anos.',
 'As vedações são independentes: cumprir o prazo não salva o objeto proibido.'),
('r07', '8.2', 'A qualificação de entidade como organização social é ato discricionário do Poder Executivo, e o vínculo com o poder público se formaliza por contrato de gestão.',
 'Certo', 'Lei 9.637/1998. A OSCIP, ao contrário, tem qualificação vinculada (Ministério da Justiça) e firma termo de parceria (Lei 9.790/1999).',
 'OS: discricionária + contrato de gestão. OSCIP: vinculada + termo de parceria. A banca troca os pares.'),
('r08', '8.2', 'No marco regulatório das organizações da sociedade civil, o termo de fomento é o instrumento adequado quando a proposta de parceria parte da administração pública.',
 'Errado', 'Lei 13.019/2014: termo de colaboração (proposta da Administração), termo de fomento (proposta da OSC), ambos com transferência de recursos; acordo de cooperação, sem transferência de recursos.',
 'Colaboração = ideia da Administração. Fomento = ideia da OSC.'),
('r09', '8.2', 'Segundo o STF, na ADI 1.923, a contratação de organizações sociais pelo poder público é constitucional, mas deve observar procedimento público, objetivo e impessoal, em respeito aos princípios do art. 37 da Constituição.',
 'Certo', 'ADI 1.923 (2015): o modelo das OS é constitucional; qualificação, celebração do contrato de gestão, contratações e seleção de pessoal devem ser conduzidas de forma pública, objetiva e impessoal.', None),
('r10', '8.2', 'O Decreto nº 9.203/2017 inclui entre as diretrizes da governança pública articular instituições e coordenar processos para melhorar a integração entre os diferentes níveis e esferas do setor público, com vistas a gerar, preservar e entregar valor público.',
 'Certo', 'Art. 4º, IV. É o ponto em que o decreto encontra o subitem 8.2 (articulação interinstitucional).', None),

# ------------------------------------------------------------------ 8.3 · coprodução, participação, transparência
('c01', '8.3', 'Coprodução de serviços públicos é o arranjo em que cidadãos ou organizações da sociedade contribuem com recursos próprios, como tempo e conhecimento, para a produção do serviço, ao lado dos agentes públicos.',
 'Certo', 'Conceito de Elinor Ostrom (1996): insumos para produzir um bem ou serviço são fornecidos por indivíduos que não pertencem à mesma organização. Exemplos: vigilância comunitária, mutirões, conselhos que planejam e avaliam.', None),
('c02', '8.3', 'A coprodução do bem público equivale à terceirização, pois em ambas o Estado transfere a execução do serviço a um particular mediante remuneração.',
 'Errado', 'Na coprodução o Estado não sai de cena: cidadão e poder público produzem juntos. Terceirização e concessão transferem a execução mediante contrato.', None),
('c03', '8.3', 'Na escada da participação de Arnstein, a consulta e a informação situam-se nos degraus de concessão mínima de poder (tokenism), abaixo dos degraus de parceria, delegação de poder e controle cidadão.',
 'Certo', 'Arnstein (1969), oito degraus: manipulação e terapia (não participação); informação, consulta e pacificação (concessão mínima); parceria, delegação de poder e controle cidadão (poder cidadão).', None),
('c04', '8.3', 'Na escada de Arnstein, a pacificação (placation) é o degrau mais alto de poder cidadão, pois os cidadãos passam a ocupar assentos em conselhos e comitês.',
 'Errado', 'Pacificação é o topo do tokenism: cidadãos têm assento, mas quem decide continua sendo o poder público. O degrau mais alto é o controle cidadão.', None),
('c05', '8.3', 'Transparência ativa é a divulgação de informações de interesse público por iniciativa da própria administração, independentemente de requerimento.',
 'Certo', 'LAI (Lei 12.527/2011), art. 3º, II, e art. 8º. Transparência passiva é a resposta a pedidos de acesso (prazo de 20 dias, prorrogável por mais 10).', None),
('c06', '8.3', 'Segundo a Lei de Acesso à Informação, todos os municípios estão obrigados a divulgar na internet as informações de transparência ativa previstas no art. 8º.',
 'Errado', 'Art. 8º, § 4º: municípios com população de até 10 mil habitantes ficam dispensados da divulgação obrigatória na internet, mantida a obrigação de divulgar em tempo real a execução orçamentária e financeira (LC 131/2009).', None),
('c07', '8.3', 'A Lei de Acesso à Informação adota a observância da publicidade como preceito geral e do sigilo como exceção.',
 'Certo', 'Art. 3º, I, da LAI.', None),
('c08', '8.3', 'A Lei de Responsabilidade Fiscal assegura a transparência mediante, entre outros meios, o incentivo à participação popular e a realização de audiências públicas durante os processos de elaboração e discussão dos planos, da LDO e dos orçamentos.',
 'Certo', 'LRF, art. 48, § 1º, I (redação da LC 131/2009).', None),
('c09', '8.3', 'A participação cidadã na gestão pública restringe-se à fase de formulação das políticas, não alcançando a implementação nem a avaliação.',
 'Errado', 'Participação e coprodução podem ocorrer em todo o ciclo: planejamento (co-planejamento), desenho, execução (co-entrega) e avaliação (co-avaliação), na classificação de Bovaird.', None),
('c10', '8.3', 'Entre as diretrizes da governança pública previstas no Decreto nº 9.203/2017 está promover a comunicação aberta, voluntária e transparente das atividades e dos resultados da organização, de maneira a fortalecer o acesso público à informação.',
 'Certo', 'Art. 4º, XI. É a transparência ativa dentro da política de governança.', None),

# ------------------------------------------------------------------ 8.4 · valor público e cadeia de valor
('v01', '8.4', 'No triângulo estratégico de Mark Moore, a criação de valor público depende do alinhamento entre a definição do valor a ser produzido, o ambiente autorizador, que confere legitimidade e apoio, e a capacidade operacional.',
 'Certo', 'Moore, Creating Public Value (1995): valor público, legitimidade e suporte, capacidade operacional. O gestor público age como estrategista, não como mero executor.', None),
('v02', '8.4', 'Para Moore, o gestor público deve limitar-se a executar fielmente os mandatos legislativos, sem buscar ativamente oportunidades de criar valor para a sociedade.',
 'Errado', 'Moore vê o gestor como explorador que procura, com imaginação, aumentar o valor público produzido, dentro do ambiente autorizador.', None),
('v03', '8.4', 'Na cadeia de valor da gestão pública, a eficácia relaciona os produtos entregues aos insumos utilizados, ao passo que a eficiência mede o alcance das metas de entrega de produtos.',
 'Errado', 'Inverteu. Eficiência = relação entre produtos e insumos (custo). Eficácia = quantidade e qualidade dos produtos entregues ao usuário (alcance de metas). Efetividade = impactos gerados na sociedade.',
 'Troca entre eficiência e eficácia é a pegadinha mais frequente da cadeia de valor.'),
('v04', '8.4', 'No modelo dos 6Es do desempenho, economicidade, execução e excelência referem-se à dimensão de esforço, enquanto eficiência, eficácia e efetividade referem-se à dimensão de resultado.',
 'Certo', 'Martins e Marini, Um guia de governança para resultados (2010). Esforço: economicidade, excelência, execução. Resultado: eficiência, eficácia, efetividade.', None),
('v05', '8.4', 'A efetividade, na cadeia de valor público, refere-se aos impactos gerados pelos produtos e serviços sobre a sociedade, isto é, à transformação produzida na realidade que motivou a intervenção.',
 'Certo', 'Efetividade = impacto, outcome, mudança na situação-problema.', None),
('v06', '8.4', 'O conceito de valor público de Moore e o de valores públicos de Bozeman são idênticos: ambos designam os resultados produzidos pelo gestor público em sua organização.',
 'Errado', 'Moore (public value): valor criado pela ação gerencial, no singular. Bozeman (public values): consensos normativos sobre direitos, benefícios e obrigações de cidadãos e do Estado, no plural.', None),
('v07', '8.4', 'Segundo o Decreto nº 9.203/2017, valor público corresponde a produtos e resultados gerados, preservados ou entregues pelas atividades de uma organização que representem respostas efetivas e úteis às necessidades ou às demandas de interesse público.',
 'Certo', 'Art. 2º, II. Note os três verbos: gerados, preservados ou entregues.', None),
('v08', '8.4', 'Na cadeia de valor de uma organização pública, os macroprocessos de suporte são os que entregam diretamente produtos e serviços ao cidadão.',
 'Errado', 'Quem entrega ao cidadão são os macroprocessos finalísticos. Os de gestão (ou gerenciais) orientam e controlam; os de suporte provêm recursos (pessoas, TI, logística).', None),

# ------------------------------------------------------------------ 9.1 · conceito, governança × governabilidade, alinhamento
('g01', '9.1', 'Segundo o Decreto nº 9.203/2017, governança pública é o conjunto de mecanismos de liderança, estratégia e controle postos em prática para planejar, executar e controlar a gestão.',
 'Errado', 'Art. 2º, I: para avaliar, direcionar e monitorar a gestão. Planejar, executar, controlar (e agir) são funções da gestão.',
 'Governança: avaliar, direcionar, monitorar. Gestão: planejar, executar, controlar, agir.'),
('g02', '9.1', 'Enquanto a governança é a função direcionadora, a gestão é a função realizadora, responsável por planejar, executar e controlar as ações.',
 'Certo', 'Distinção do TCU (Referencial Básico de Governança): a governança direciona, avalia e monitora; a gestão realiza.', None),
('g03', '9.1', 'Para Bresser-Pereira, governabilidade refere-se à capacidade financeira e administrativa do Estado de implementar suas políticas, e governança, às condições políticas de legitimidade do governo.',
 'Errado', 'Inverteu. Governança = capacidade financeira e administrativa, em sentido amplo, de implementar políticas. Governabilidade = condições políticas: legitimidade, apoio, instituições capazes de intermediar interesses.',
 'A inversão governança/governabilidade é a pegadinha mais provável do subitem 9.1.'),
('g04', '9.1', 'A capacidade das instituições políticas de intermediar interesses dentro do Estado e na sociedade civil relaciona-se à governabilidade, e não à governança.',
 'Certo', 'Bresser-Pereira (1998) lista entre as condições de governabilidade a adequação das instituições políticas capazes de intermediar interesses. O Cebraspe usou exatamente essa distinção no TCDF 2024.', None),
('g05', '9.1', 'O Plano Diretor da Reforma do Aparelho do Estado tinha como objetivo aumentar a governança do Estado, entendida como sua capacidade administrativa de governar com efetividade e eficiência.',
 'Certo', 'Literal do PDRAE (1995): o governo brasileiro não carecia de governabilidade, mas de governança.', None),
('g06', '9.1', 'Na perspectiva da teoria da agência aplicada ao setor público, os gestores públicos são o principal, e a sociedade é o agente a quem se delega a gestão.',
 'Errado', 'Inverteu. A sociedade (cidadãos) é o principal; governantes e gestores são agentes. A governança existe para reduzir o conflito de agência e a assimetria de informação.', None),
('g07', '9.1', 'O alinhamento estratégico abrange tanto o desdobramento da estratégia dentro da organização quanto a articulação de objetivos entre organizações e partes interessadas, o que o TCU denomina alinhamento transorganizacional.',
 'Certo', 'Decreto, art. 5º, II (alinhamento entre organizações e partes interessadas); TCU, componente "alinhamento transorganizacional" do mecanismo estratégia.', None),
('g08', '9.1', 'O conceito de governança aplica-se exclusivamente ao nível organizacional, não alcançando as políticas públicas nem as relações entre Estado e sociedade.',
 'Errado', 'O TCU identifica perspectivas de sociedade e Estado, de entes federativos e políticas públicas, de órgãos e entidades e de atividades intraorganizacionais. Há referencial próprio para governança de políticas públicas.', None),
('g09', '9.1', 'Para o Banco Mundial (1992), governança é a maneira pela qual o poder é exercido na administração dos recursos econômicos e sociais de um país, com vistas ao desenvolvimento.',
 'Certo', 'Definição clássica do documento Governance and Development (1992), ponto de partida dos debates dos anos 1990.', None),

# ------------------------------------------------------------------ 9.2 · mecanismos
('k01', '9.2', 'De acordo com o Decreto nº 9.203/2017, a liderança compreende um conjunto de práticas de natureza humana ou comportamental, exercidas nos principais cargos das organizações, que asseguram condições mínimas para a boa governança: integridade, competência, responsabilidade e motivação.',
 'Certo', 'Art. 5º, I, com as alíneas a a d.', None),
('k02', '9.2', 'O mecanismo de controle, segundo o Decreto nº 9.203/2017, compreende a definição de diretrizes, objetivos, planos e ações, além de critérios de priorização e alinhamento entre organizações e partes interessadas.',
 'Errado', 'Essa é a definição de estratégia (art. 5º, II). Controle (art. 5º, III) compreende processos estruturados para mitigar riscos e garantir execução ordenada, ética, econômica, eficiente e eficaz, com preservação da legalidade e da economicidade.',
 'A banca cola a definição de um mecanismo no nome de outro.'),
('k03', '9.2', 'Entre as condições mínimas para o exercício da boa governança associadas ao mecanismo de liderança, o Decreto nº 9.203/2017 menciona a transparência.',
 'Errado', 'As condições são integridade, competência, responsabilidade e motivação. Transparência é princípio (art. 3º, VI).', None),
('k04', '9.2', 'Na terceira edição do Referencial Básico de Governança Organizacional do TCU (2020), a prática "gerir riscos" integra o mecanismo de estratégia.',
 'Certo', 'Na 3ª edição, estratégia reúne: gerir riscos, estabelecer a estratégia, promover a gestão estratégica, monitorar o alcance dos resultados organizacionais e monitorar o desempenho das funções de gestão.',
 'Na 2ª edição (2014), "gestão de riscos e controle interno" estava no mecanismo de controle. Se o item citar a edição, responda por ela.'),
('k05', '9.2', 'No Referencial Básico de Governança Organizacional do TCU, promover a transparência, garantir a accountability, avaliar a satisfação das partes interessadas e avaliar a efetividade da auditoria interna são práticas do mecanismo de controle.',
 'Certo', '3ª edição (2020), mecanismo controle.', None),
('k06', '9.2', 'Estabelecer o modelo de governança, promover a integridade e promover a capacidade da liderança são práticas do mecanismo de liderança no referencial do TCU.',
 'Certo', '3ª edição (2020), mecanismo liderança.', None),
('k07', '9.2', 'A auditoria interna governamental, segundo o Decreto nº 9.203/2017, deve adicionar valor e melhorar as operações das organizações, por meio da avaliação e da melhoria da eficácia dos processos de gerenciamento de riscos, dos controles e da governança.',
 'Certo', 'Art. 18. Inclui trabalhos de avaliação e consultoria independentes, abordagem baseada em risco e prevenção, detecção e investigação de fraudes.', None),
('k08', '9.2', 'O sistema de gestão de riscos previsto no Decreto nº 9.203/2017 deve estabelecer controles internos no nível mais rigoroso possível, independentemente da relação custo-benefício.',
 'Errado', 'Art. 17, III: controles internos proporcionais aos riscos, considerando causas, fontes, consequências e impactos, observada a relação custo-benefício.', None),
('k09', '9.2', 'Para o TCU, a auditoria interna e a ouvidoria são instâncias internas de apoio à governança, ao passo que o Congresso Nacional e o próprio TCU são instâncias externas de governança.',
 'Certo', 'Referencial do TCU (2014): instâncias externas (Congresso, TCU), externas de apoio (auditoria independente, controle social organizado), internas (conselhos, alta administração) e internas de apoio (auditoria interna, ouvidoria, comitês).', None),

# ------------------------------------------------------------------ 9.3 · valor público, resultados, sustentabilidade, avaliação
('a01', '9.3', 'A avaliação de impacto de uma política pública busca estimar o efeito causal da intervenção, comparando os resultados observados com o que teria ocorrido sem ela, o chamado contrafactual.',
 'Certo', 'Guia de avaliação ex post (Casa Civil/IPEA, 2018). Sem contrafactual não há como atribuir a mudança à política.', None),
('a02', '9.3', 'A avaliação ex ante ocorre depois da implementação da política e tem por objetivo medir os impactos efetivamente produzidos.',
 'Errado', 'Ex ante ocorre antes: diagnóstico do problema, desenho, modelo lógico, custos e benefícios esperados. Medir impactos é avaliação ex post.', None),
('a03', '9.3', 'Desde a Emenda Constitucional nº 109/2021, a Constituição determina que os órgãos e as entidades da administração pública, individual ou conjuntamente, realizem avaliação das políticas públicas, inclusive com divulgação do objeto avaliado e dos resultados alcançados, na forma da lei.',
 'Certo', 'Art. 37, § 16, da CF.', None),
('a04', '9.3', 'Produtos (outputs) e impactos (outcomes) são conceitos equivalentes na avaliação de políticas públicas, pois ambos expressam o que a política entregou.',
 'Errado', 'Produto é o bem ou serviço entregue (vacinas aplicadas). Resultado e impacto são as mudanças provocadas (queda da mortalidade). Medir só produtos é confundir eficácia com efetividade.', None),
('a05', '9.3', 'O Decreto nº 9.203/2017 prevê como diretriz avaliar as propostas de criação, expansão ou aperfeiçoamento de políticas públicas e de concessão de incentivos fiscais e aferir, sempre que possível, seus custos e benefícios.',
 'Certo', 'Art. 4º, VII.', None),
('a06', '9.3', 'Sustentabilidade, no contexto da geração de valor público, limita-se à dimensão ambiental, sem relação com a viabilidade econômica e social das políticas ao longo do tempo.',
 'Errado', 'Sustentabilidade envolve as dimensões econômica, social e ambiental e a perspectiva intergeracional (Relatório Brundtland, 1987).', None),
('a07', '9.3', 'Os mecanismos, as instâncias e as práticas de governança devem incluir, no mínimo, formas de acompanhamento de resultados, soluções para melhoria do desempenho das organizações e instrumentos de promoção do processo decisório fundamentado em evidências.',
 'Certo', 'Art. 6º, parágrafo único, do Decreto 9.203.', None),
('a08', '9.3', 'Gerar valor público equivale a cumprir as metas físicas de produção da organização, independentemente de os produtos atenderem às necessidades da sociedade.',
 'Errado', 'O decreto exige respostas efetivas e úteis às necessidades ou demandas de interesse público que modifiquem aspectos da sociedade. Cumprir meta sem efeito é eficácia sem efetividade.', None),

# ------------------------------------------------------------------ 9.4 · Decreto 9.203/2017
('d01', '9.4', 'O Decreto nº 9.203/2017 dispõe sobre a política de governança da administração pública federal direta, autárquica e fundacional, aplicando-se também às empresas públicas e às sociedades de economia mista.',
 'Errado', 'Art. 1º: só a administração direta, autárquica e fundacional. As estatais têm regime próprio de governança (Lei 13.303/2016).',
 'Âmbito do decreto: direta, autárquica e fundacional. Incluir estatais é a pegadinha do art. 1º.'),
('d02', '9.4', 'São princípios da governança pública, conforme o Decreto nº 9.203/2017, a capacidade de resposta, a integridade, a confiabilidade, a melhoria regulatória, a prestação de contas e responsabilidade e a transparência.',
 'Certo', 'Art. 3º: são seis princípios, nessa ordem.', None),
('d03', '9.4', 'A eficiência e a legalidade figuram entre os princípios da governança pública expressamente listados no Decreto nº 9.203/2017.',
 'Errado', 'Legalidade e eficiência são princípios da Administração (CF, art. 37, caput), não do art. 3º do decreto. Os seis do decreto: capacidade de resposta, integridade, confiabilidade, melhoria regulatória, prestação de contas e responsabilidade, transparência.',
 'O examinador mistura princípios da CF, do TCU (equidade, legitimidade, probidade) e do decreto.'),
('d04', '9.4', 'Fazer incorporar padrões elevados de conduta pela alta administração para orientar o comportamento dos agentes públicos é princípio da governança pública previsto no Decreto nº 9.203/2017.',
 'Errado', 'É diretriz (art. 4º, V). O decreto tem 6 princípios (art. 3º) e 11 diretrizes (art. 4º). Diretrizes começam por verbos.',
 'Truque para separar: princípios são substantivos curtos; diretrizes são frases com verbo no infinitivo.'),
('d05', '9.4', 'Implementar controles internos fundamentados na gestão de risco, que privilegiará ações estratégicas de prevenção antes de processos sancionadores, é diretriz da governança pública.',
 'Certo', 'Art. 4º, VI.', None),
('d06', '9.4', 'Para os fins do Decreto nº 9.203/2017, integram a alta administração os Ministros de Estado, os ocupantes de cargos de natureza especial, os ocupantes de cargo de nível 6 do Grupo-Direção e Assessoramento Superiores e os presidentes e diretores de autarquias e fundações públicas, ou autoridades de hierarquia equivalente.',
 'Certo', 'Art. 2º, III. Autarquias "inclusive as especiais".', 'Trocar o nível 6 por nível 5 ou incluir diretores de estatais torna o item errado.'),
('d07', '9.4', 'Gestão de riscos, segundo o Decreto nº 9.203/2017, é processo de natureza permanente, estabelecido, direcionado e monitorado pela alta administração, destinado a fornecer segurança absoluta quanto à realização dos objetivos da organização.',
 'Errado', 'Art. 2º, IV: segurança razoável, não absoluta.', '"Absoluta" no lugar de "razoável" é troca típica.'),
('d08', '9.4', 'Cabe à alta administração dos órgãos e das entidades implementar e manter mecanismos, instâncias e práticas de governança, em consonância com os princípios e as diretrizes do Decreto nº 9.203/2017.',
 'Certo', 'Art. 6º.', None),
('d09', '9.4', 'O Comitê Interministerial de Governança tem por finalidade assessorar o Presidente da República na condução da política de governança da administração pública federal e é coordenado pelo Ministro de Estado Chefe da Casa Civil.',
 'Certo', 'Arts. 7º-A e 8º-A (redação do Decreto 9.901/2019).', None),
('d10', '9.4', 'O Comitê Interministerial de Governança é coordenado pelo Ministro de Estado da Controladoria-Geral da União, a quem compete o voto de qualidade em caso de empate.',
 'Errado', 'O coordenador é o Ministro-Chefe da Casa Civil (art. 8º-A, I), que tem voto de qualidade (art. 8º-B). A CGU é membro, não coordenadora.', None),
('d11', '9.4', 'O Comitê Interministerial de Governança reúne-se, em caráter ordinário, trimestralmente.',
 'Certo', 'Art. 8º-B (Decreto 9.901/2019). Em caráter extraordinário, sempre que necessário.', None),
('d12', '9.4', 'Compete ao Comitê Interministerial de Governança aprovar manuais e guias com medidas, mecanismos e práticas organizacionais que contribuam para a implementação dos princípios e das diretrizes de governança pública.',
 'Certo', 'Competência do CIG prevista no decreto. Na prática, o "Guia da Política de Governança Pública" (2018) foi aprovado nesse contexto.', None),
('d13', '9.4', 'Os comitês internos de governança dos órgãos e entidades têm, entre suas competências, auxiliar a alta administração na implementação e na manutenção de processos, estruturas e mecanismos adequados à incorporação dos princípios e das diretrizes da governança.',
 'Certo', 'Art. 15-A, incluído pelo Decreto 9.901/2019.', 'Não confunda o CIG (interministerial, assessora o Presidente) com os comitês internos de cada órgão.'),
('d14', '9.4', 'O sistema de gestão de riscos e controles internos previsto no Decreto nº 9.203/2017 deve ser integrado ao processo de planejamento estratégico e aos seus desdobramentos, às atividades, aos processos de trabalho e aos projetos em todos os níveis da organização.',
 'Certo', 'Art. 17, II.', None),
('d15', '9.4', 'Os programas de integridade previstos no Decreto nº 9.203/2017 estruturam-se nos eixos de comprometimento e apoio da alta administração, existência de unidade responsável, análise, avaliação e gestão dos riscos associados à integridade, e monitoramento contínuo dos atributos do programa.',
 'Certo', 'Art. 19 (texto original do decreto).', 'Em 2023 o Decreto 11.529 criou o Sitai e passou a tratar dos programas de integridade. Confira no texto consolidado se o art. 19 continua vigente antes da prova.'),
('d16', '9.4', 'Manter processo decisório orientado pelas evidências, pela conformidade legal, pela qualidade regulatória, pela desburocratização e pelo apoio à participação da sociedade é diretriz da governança pública.',
 'Certo', 'Art. 4º, VIII.', None),
('d17', '9.4', 'Confiabilidade, como princípio de governança, refere-se à capacidade das instituições de minimizar as incertezas para os cidadãos nos campos econômico, social e político.',
 'Certo', 'Conceito do Guia da Política de Governança Pública (Casa Civil, 2018).', None),
('d18', '9.4', 'Capacidade de resposta, princípio da governança pública, consiste na competência de a instituição atender de forma eficiente e eficaz às necessidades das partes interessadas, inclusive antevendo problemas e prevendo tendências.',
 'Certo', 'Guia da Política de Governança Pública (2018).', None),
]
